        backgroundColor: ACCENTS.line.fill,
        fill: true,
        tension: 0.35,
        pointRadius: 4,
        pointHoverRadius: 6,
        pointHitRadius: 10,
        pointBackgroundColor: ACCENTS.line.border,
      },
    ],
  }), [])

  const options = useMemo(
    () => buildChartOptions(resolvedTheme === 'dark' ? 'dark' : 'light', notifyChartRender),
    [resolvedTheme, notifyChartRender]
